    max_val = max(r, g, b)
    min_val = min(r, g, b)

    # Calculate the difference between max and min
    diff = max_val - min_val

    # Calculate the Hue
    if max_val == min_val:
        h = 0
    elif max_val == r:
        h = (60 * ((g - b) / diff) + 360) % 360
    elif max_val == g:
        h = (60 * ((b - r) / diff) + 120) % 360
    elif max_val == b:
        h = (60 * ((r - g) / diff) + 240) % 360

    # Calculate the Saturation
    if max_val == 0:
        s = 0
    else:
        s = (diff / max_val) * 100

    # Calculate the Value
    v = max_val * 100

    return (h, s, v)

