def geometric_sum(n):
    # Base case: if n is 0, return 1 (since 2^0 = 1)
    if n == 0:
        return 1
    # Recursive case: return 1 / (2^n) plus the geometric sum of n-1
    else:
        return 1 / (2 ** n) + geometric_sum(n - 1)

