def count_no_of_ways(n, k):
    mod = 1000000007
    same, diff = 0, k

    if n == 0:
        return 0
    if n == 1:
        return k

    for i in range(2, n + 1):
        same = diff
        diff = (k - 1) * (same + diff) % mod

    return (same + diff) % mod

